import{_ as e,o as l,c as t,a2 as i}from"./chunks/framework.D7WGirly.js";const f=JSON.parse('{"title":"序列比对知识库","description":"","frontmatter":{"title":"序列比对知识库","layout":"doc","pageClass":"academic-home","sidebar":false,"aside":false,"outline":false,"prev":false,"next":false},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),r={name:"index.md"};function h(s,a,o,n,d,m){return l(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="序列比对知识库" tabindex="-1">序列比对知识库 <a class="header-anchor" href="#序列比对知识库" aria-label="Permalink to &quot;序列比对知识库&quot;">​</a></h1><p>序列比对是将两个或多个序列排列在一起，标明其相似之处。序列中可以插入间隔（通常用短横线“-”表示）。对应的相同或相似的符号（在核酸中是A, T（或U）, C, G，在蛋白质中是氨基酸残基的单字母表示）排列在同一列上。这一方法常用于研究由共同祖先进化而来的序列，特别是如蛋白质序列或DNA序列等生物序列。在比对中，错配与突变相应，而空位与插入或缺失对应。序列比对还可用于语言进化或文本间相似性之类的研究。</p><h2 id="比对基础" tabindex="-1">比对基础 <a class="header-anchor" href="#比对基础" aria-label="Permalink to &quot;比对基础&quot;">​</a></h2><p>序列比对的基本问题、算法与评价方法。</p><ul><li><a href="./basics/pairwise.html">双序列比对</a></li><li><a href="./basics/multiple.html">多序列比对</a></li><li><a href="./basics/genome.html">基因组比对</a></li><li><a href="./basics/metrics.html">评价指标</a></li></ul><h2 id="重比对" tabindex="-1">重比对 <a class="header-anchor" href="#重比对" aria-label="Permalink to &quot;重比对&quot;">​</a></h2><p>按分割方式整理独立重比对工具和 MSA 工具中的迭代优化方法。</p><ul><li><a href="./realignment/overview.html">重比对概述</a></li><li><a href="./realignment/standalone.html">独立重比对工具</a></li><li><a href="./realignment/in-msa.html">MSA 工具中的重比对</a></li></ul><h2 id="数据与评测" tabindex="-1">数据与评测 <a class="header-anchor" href="#数据与评测" aria-label="Permalink to &quot;数据与评测&quot;">​</a></h2><p>真实与模拟数据集，以及可复用的数据生成流程。</p><ul><li><a href="./data/datasets.html">数据集目录</a></li><li><a href="./data/simulation.html">模拟数据生成</a></li></ul><h2 id="软件指南" tabindex="-1">软件指南 <a class="header-anchor" href="#软件指南" aria-label="Permalink to &quot;软件指南&quot;">​</a></h2><p>课题组软件及第三方工具的安装、使用方法与实践经验。</p><ul><li><a href="./software/lab.html">课题组软件</a></li><li><a href="./software/third-party.html">第三方比对工具</a></li><li><a href="./software/cactus.html">Cactus 安装与使用</a></li><li><a href="./software/unialigner.html">Unialigner 安装指南</a></li></ul><h2 id="开发工具" tabindex="-1">开发工具 <a class="header-anchor" href="#开发工具" aria-label="Permalink to &quot;开发工具&quot;">​</a></h2><p>常用数据处理脚本、索引库和序列处理模块。</p><ul><li><a href="./development/scripts.html">数据处理脚本</a></li><li><a href="./development/libraries.html">开发库</a></li></ul><h2 id="论文成果" tabindex="-1">论文成果 <a class="header-anchor" href="#论文成果" aria-label="Permalink to &quot;论文成果&quot;">​</a></h2><p>按研究方向整理的课题组论文及相关软件。</p><ul><li><a href="./publications/papers.html">论文列表</a></li></ul><h2 id="多基因组数据资源" tabindex="-1">多基因组数据资源 <a class="header-anchor" href="#多基因组数据资源" aria-label="Permalink to &quot;多基因组数据资源&quot;">​</a></h2><p><a href="https://github.com/malabz/MGA-Dataset" target="_blank" rel="noreferrer">MGA-Dataset</a> 持续整理多基因组比对与泛基因组研究的数据集说明、官方来源和下载入口。原始数据由各发布方提供，仓库提供分类导航与使用说明。</p>',22)])])}const u=e(r,[["render",h]]);export{f as __pageData,u as default};
